"""Reads the help of the originals, which is the source for what the wiki says about a command: the official English
help in third_party/blitz3d_soloud/BLITZ3D_INSTALL/help and the German blitzforum.de help in third_party/blitzforum-help.

  helpref.py show NAME...   Prints what the help says about the commands, as plain text.
  helpref.py page PAGE      Prints it for every command of a wiki page, such as Blitz3D-Textures.

The help is only reference material: the wiki text is written in our own words, not copied from it.
"""
import html
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import wiki  # noqa: E402

HELP = os.path.join(wiki.ROOT, "third_party", "blitzforum-help", "commands")
BADGES = {"B2D": "Blitz2D", "B+": "BlitzPlus", "B3D": "Blitz3D"}
OFFICIAL = os.path.join(wiki.ROOT, "third_party", "blitz3d_soloud", "BLITZ3D_INSTALL", "help", "commands")
_index = None
_official = None


def official(key):
    """The official English help of a command as plain text, or None."""
    global _official
    if _official is None:
        _official = {}
        for d, _, files in os.walk(OFFICIAL):
            if d.endswith("_commands"):
                for fn in files:
                    if fn.endswith(".htm"):
                        _official.setdefault(fn[:-4].lower(), os.path.join(d, fn))
    path = _official.get(key)
    if not path:
        return None
    with open(path, encoding="iso-8859-1") as f:
        body = f.read()
    body = re.sub(r"<(script|style)[^>]*>.*?</\1>", "", body, flags=re.S | re.I)
    return text(body)


def index():
    global _index
    if _index is None:
        _index = {}
        for d, _, files in os.walk(HELP):
            for fn in files:
                if fn.endswith(".htm"):
                    _index.setdefault(fn[:-4].lower(), os.path.join(d, fn))
    return _index


def text(fragment):
    fragment = re.sub(r"<br\s*/?>", "\n", fragment)
    fragment = re.sub(r"</(tr|p|div)>", "\n", fragment)
    fragment = re.sub(r"</td>", " | ", fragment)
    fragment = re.sub(r"<[^>]+>", "", fragment)
    lines = [re.sub(r"[ \t\xa0]+", " ", l).strip() for l in html.unescape(fragment).split("\n")]
    joined = re.sub(r"\n{3,}", "\n\n", "\n".join(lines)).strip()
    return re.sub(r"\n+\|\n+", " | ", joined)


def read(key):
    path = index().get(key)
    if not path:
        return None
    with open(path, encoding="iso-8859-1") as f:
        body = f.read()
    out = {"dialects": [BADGES[a] for a in re.findall(r'<img src="[^"]*help_\w+\.png" alt="([^"]+)"', body) if a in BADGES]}
    for label, name in (("Aufruf", "syntax"), ("Parameter", "params"), ("R.ckgabewert", "returns"),
                        ("Beschreibung", "description"), ("Zusatzinformation", "notes"), ("Beispiel", "example")):
        m = re.search(r"<b>%s</b>(.*?)(?=<b>(?:Aufruf|Parameter|R.ckgabewert|Beschreibung|Zusatzinformation|Beispiel|Siehe auch)</b>|<div id=\"pages_bottom\")" % label, body, re.S)
        out[name] = text(m.group(1)) if m else ""
    return out


def show(c):
    r = read(c.key)
    print("=== %s  (%s)" % (c.name, c.page))
    o = official(c.key)
    if o:
        o = re.sub(r"\n{2,}", "\n", o.split("| Example")[0].replace("Blitz3D Docs", "").strip())
    print("-- official help: %s" % (o if o else "(none)"))
    if not r:
        print("(not in the help)\n")
        return
    print("works in: " + ", ".join(r["dialects"]))
    for k in ("syntax", "params", "returns", "description", "notes"):
        if r[k]:
            print("-- %s: %s" % (k, r[k]))
    print()


def main():
    cmds = wiki.load()
    if sys.argv[1] == "show":
        names = {n.lower() for n in sys.argv[2:]}
        for c in cmds:
            if c.key in names:
                show(c)
    elif sys.argv[1] == "page":
        for c in sorted(cmds, key=lambda c: c.key):
            if c.page == sys.argv[2]:
                show(c)
    return 0


if __name__ == "__main__":
    sys.exit(main())
